package com.diskree.achievetodo.certification;
import org.junit.jupiter.api.Test;import java.nio.file.Path;import java.util.*;import static org.junit.jupiter.api.Assertions.*;
class PhaseAMixedPerfectRunCertificationTest{@Test void threeFrozenAndGroupsRetainTheRealNativePrerequisite()throws Exception{var cases=PhaseAMixedPerfectRunCertification.cases(Path.of("").toAbsolutePath());assertEquals(3,cases.size());assertEquals(3,PhaseAMixedPerfectRunEvidenceValidation.canaryKeys(cases).size());for(var row:cases){assertEquals(1,row.getAsJsonArray("alternatives").size());assertTrue(row.getAsJsonObject("frozenConditions").getAsJsonObject("player").getAsJsonObject("type_specific").getAsJsonObject("advancements").get(PhaseAMixedPerfectRunCertification.PREREQUISITE).getAsBoolean());}}}
